require __DIR__.'/config.php';$u=require_login();$b=require_business();if(!can('settings')){http_response_code(403);exit('Forbidden');}$pdo=db();
$w=$pdo->prepare("SELECT * FROM whatsapp_settings WHERE business_id=? LIMIT 1");$w->execute([$b['id']]);$w=$w->fetch() ?: ['phone_number_id'=>'','access_token'=>'','graph_version'=>'v23.0','enabled'=>0,'test_phone'=>''];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='business'){$s=$pdo->prepare("UPDATE businesses SET phone=?,address=?,updated_at=NOW() WHERE id=?");$s->execute([trim($_POST['phone']),trim($_POST['address']),$b['id']]);flash('Business settings saved.');}
 if($action==='hero'){$newHero=hero_upload('hero_image');$oldHero=$b['hero_image']??null;$s=$pdo->prepare('UPDATE businesses SET hero_image=?,updated_at=NOW() WHERE id=?');$s->execute([$newHero,$b['id']]);delete_hero_file($oldHero);audit((int)$b['id'],(int)$u['id'],'business.hero_updated','Primary hero image replaced');flash('Hero image updated.');}
 if($action==='remove_hero'){$oldHero=$b['hero_image']??null;$s=$pdo->prepare('UPDATE businesses SET hero_image=NULL,updated_at=NOW() WHERE id=?');$s->execute([$b['id']]);delete_hero_file($oldHero);audit((int)$b['id'],(int)$u['id'],'business.hero_removed','Primary hero image removed');flash('Hero image removed.');}
 if($action==='whatsapp'){$s=$pdo->prepare("INSERT INTO whatsapp_settings(business_id,phone_number_id,access_token,graph_version,enabled,test_phone) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE phone_number_id=VALUES(phone_number_id),access_token=VALUES(access_token),graph_version=VALUES(graph_version),enabled=VALUES(enabled),test_phone=VALUES(test_phone)");$s->execute([$b['id'],trim($_POST['phone_number_id']),trim($_POST['access_token']),trim($_POST['graph_version']),isset($_POST['enabled'])?1:0,trim($_POST['test_phone'])]);flash('WhatsApp settings saved.');}
}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('settings.php');}
