<script>(function(){if(!window.AndroidFCM)return;var panel=document.getElementById('nativeVoicePanel'),toggle=document.getElementById('nativeVoiceEnabled'),test=document.getElementById('nativeVoiceTest'),status=document.getElementById('nativeVoiceStatus');if(!panel||!toggle)return;panel.style.display='block';toggle.checked=AndroidFCM.isVoiceEnabled();toggle.addEventListener('change',function(){AndroidFCM.setVoiceEnabled(toggle.checked);status.textContent=toggle.checked?'Voice notifications enabled.':'Voice notifications disabled.'});test&&test.addEventListener('click',function(){AndroidFCM.setVoiceEnabled(true);toggle.checked=true;AndroidFCM.testVoice();status.textContent='Test voice sent.'});})();</script>
